/* ---------- helpers ---------- */
function txt(g, x, y, s, size, fill, anchor, bold) {
  var t = g.text(s);
  t.font({ family: 'sans-serif', size: size, anchor: anchor || 'start', weight: bold ? 'bold' : 'normal' });
  t.fill(fill || '#000');
  t.attr({ x: x, y: y });
  t.each(function () { this.attr({ x: x, dy: 0 }); });
  return t;
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}
function leader(g, pts, withHalo) {
  var s = pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
  if (withHalo) g.polyline(s).fill('none').stroke({ color: '#fff', width: 5, linecap: 'round' });
  return g.polyline(s).fill('none').stroke({ color: '#000', width: 1.7, linecap: 'round' });
}
function attach(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

