/* ---------- anodes, stems, static bubble clusters ---------- */
var seed = 7;
function rnd() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }

function anodeGeom() {
  var hw = wearOn ? 80 : 102.5;
  var top = wearOn ? 300 : 313;
  var bot = wearOn ? 474 : 548;
  return [{ cx: 452.5, hw: hw, top: top, bot: bot }, { cx: 747.5, hw: hw, top: top, bot: bot }];
}

function buildAnodes() {
  gAnodes.clear(); gStems.clear(); gStatic.clear();
  seed = 7;
  var gs = anodeGeom();
  gs.forEach(function (a) {
    var forkBot = a.top - 14, forkTop = a.top - 50, stemTop = 198;
    var prongBot = a.top + (wearOn ? 58 : 72);
    gStems.rect(28, forkTop - stemTop).move(a.cx - 14, stemTop).fill(gradStem);
    gStems.polygon([[a.cx - 14, forkTop], [a.cx + 14, forkTop],
    [a.cx + 0.62 * a.hw, forkBot], [a.cx - 0.62 * a.hw, forkBot]]).fill(gradStem);
    [-0.50, -0.107, 0.283].forEach(function (f) {
      gStems.rect(22, prongBot - forkBot + 2).move(a.cx + f * a.hw, forkBot - 1).fill(gradStem);
    });

    /* static bubble ring (as in the source figure) */
    var n = Math.round((a.bot - a.top) / 7);
    for (var i = 0; i < n; i++) {
      var yy = a.top + 78 + rnd() * (a.bot - a.top - 74);
      var r1 = 2.4 + rnd() * 4.4;
      gStatic.circle(2 * r1).center(a.cx - a.hw - 3 - rnd() * 11, yy).fill('#fff');
      var r2 = 2.4 + rnd() * 4.4;
      gStatic.circle(2 * r2).center(a.cx + a.hw + 3 + rnd() * 11, yy).fill('#fff');
    }
    for (var j = 0; j < 26; j++) {
      var r3 = 2.4 + rnd() * 4.2;
      gStatic.circle(2 * r3).center(a.cx - a.hw + rnd() * 2 * a.hw, a.bot + 3 + rnd() * 10).fill('#fff');
    }
    /* invisible hit strips for the bubble label */
    [[a.cx - a.hw - 18, a.top + 72, 20, a.bot - a.top - 66],
    [a.cx + a.hw - 2, a.top + 72, 20, a.bot - a.top - 66],
    [a.cx - a.hw, a.bot, 2 * a.hw, 18]].forEach(function (b) {
      var hit = gStatic.rect(b[2], b[3]).move(b[0], b[1]).fill('#fff').opacity(0.001);
      attach(hit, 'Bubbles of O₂, CO and CO₂',
        'Gas bubbles at the anode',
        'Oxide ions are oxidised at the positive carbon: 2O²⁻(l) → O₂(g) + 4e⁻. The hot oxygen immediately attacks the carbon block itself, so the escaping gas is a mixture of O₂, CO and CO₂ — the anode is burned away as it works.');
    });

    /* anode block */
    var blk = gAnodes.rect(2 * a.hw, a.bot - a.top).move(a.cx - a.hw, a.top).fill('#0d0d0d').radius(wearOn ? 6 : 0);
    var fs = wearOn ? 21 : 25;
    var midY = (prongBot + a.bot) / 2;
    var t1 = txt(gAnodes, a.cx, midY - 9, 'Carbon', fs, '#ffffff', 'middle', true);
    var t2 = txt(gAnodes, a.cx, midY + fs + 1, 'anode (+)', fs, '#ffffff', 'middle', true);
    [blk, t1, t2].forEach(function (e) {
      attach(e, wearOn ? 'Carbon anode (+) — partly consumed' : 'Carbon anode (+)',
        'Carbon anode (+)',
        'The positive electrode is a block of baked petroleum coke. It is a REACTANT, not a spectator: C(s) + 2O²⁻(l) → CO₂(g) + 4e⁻. Roughly 0.4–0.5 t of carbon is burned per tonne of aluminium, so the blocks shrink and must be replaced on a schedule.');
    });
  });
}

