/* ---------- melt redraw ---------- */
function redrawMelt() {
  var pt = padTopY();
  greenRect.height(Math.max(20, pt - CAV.top));
  alPoly.plot([[CAV.x0, pt], [CAV.x1, pt], [CAV.x1, cathTop(CAV.x1)], [CAV.x0, cathTop(CAV.x0)]]);
}

/* ---------- ions ---------- */
function freePos() {
  var gs = anodeGeom(), lo = CAV.top + CRUST_H + 12, hi = padTopY() - 14;
  for (var k = 0; k < 24; k++) {
    var x = 308 + Math.random() * 586, y = lo + Math.random() * Math.max(20, hi - lo), bad = false;
    for (var i = 0; i < gs.length; i++) {
      var a = gs[i];
      if (x > a.cx - a.hw - 14 && x < a.cx + a.hw + 14 && y > a.top - 12 && y < a.bot + 14) bad = true;
    }
    if (!bad) return { x: x, y: y };
  }
  return { x: 312, y: lo + 20 };
}
function oxTarget(o) {
  var gs = anodeGeom();
  var a = Math.abs(o.x - gs[0].cx) < Math.abs(o.x - gs[1].cx) ? gs[0] : gs[1];
  if (o.y > a.bot + 6) return { x: Math.max(a.cx - a.hw + 8, Math.min(a.cx + a.hw - 8, o.x)), y: a.bot + 8 };
  var side = o.x < a.cx ? -1 : 1;
  return { x: a.cx + side * (a.hw + 9), y: Math.max(a.top + 85, Math.min(a.bot - 6, o.y)) };
}
function resetIon(o) {
  var p = freePos();
  if (o.kind === 'al') { p.y = CAV.top + CRUST_H + 8 + Math.random() * 60; }
  o.x = p.x; o.y = p.y;
  if (o.kind === 'ox') o.tgt = oxTarget(o);
  o.el.center(o.x, o.y);
}
function makeIons() {
  gIons.clear(); ions = [];
  for (var i = 0; i < 24; i++) {
    var kind = i % 2 ? 'ox' : 'al';
    var el = gIons.circle(15).fill(kind === 'al' ? '#d93025' : '#1a73e8').stroke({ color: '#fff', width: 1.6 });
    var o = { kind: kind, el: el, x: 0, y: 0 };
    resetIon(o); ions.push(o);
    attach(el, kind === 'al' ? 'Al³⁺ migrating down to the cathode' : 'O²⁻ migrating to the anode',
      kind === 'al' ? 'Al³⁺ ion' : 'O²⁻ ion',
      kind === 'al'
        ? 'Positive Al³⁺ ions are attracted to the negative carbon cathode floor, where each picks up three electrons and joins the liquid metal pad.'
        : 'Negative O²⁻ ions are attracted to the positive carbon anodes, where they give up electrons and react with the carbon to leave as CO₂, CO and O₂.');
  }
}
function moveIons(k) {
  var pt = padTopY();
  ions.forEach(function (o) {
    if (o.kind === 'al') {
      o.y += 0.95 * k;
      o.x += Math.sin(o.y * 0.05) * 0.25;
      if (o.y > pt - 8) resetIon(o); else o.el.center(o.x, o.y);
    } else {
      if (!o.tgt) o.tgt = oxTarget(o);
      var dx = o.tgt.x - o.x, dy = o.tgt.y - o.y, d = Math.sqrt(dx * dx + dy * dy);
      if (d < 7) { spawnBubbleAt(o.tgt.x, o.tgt.y); resetIon(o); return; }
      o.x += dx / d * 1.0 * k; o.y += dy / d * 1.0 * k;
      o.el.center(o.x, o.y);
    }
  });
}

/* ---------- bubbles ---------- */
function newBubble(x, y, vx) {
  if (dynBubbles.length > 230) return;
  var r = 2.2 + Math.random() * 5;
  var el = gDyn.circle(2 * r).center(x, y).fill('#ffffff').opacity(0.96);
  dynBubbles.push({ el: el, x: x, y: y, r: r, vx: vx, vy: 0.7 + Math.random() * 0.9, ph: Math.random() * 6.3 });
}
function spawnBubbleAt(x, y) { newBubble(x, y, 0); }
function spawnBubble() {
  var gs = anodeGeom(), a = gs[Math.random() < 0.5 ? 0 : 1], s = Math.random(), x, y, vx = 0;
  if (s < 0.4) { x = a.cx - a.hw - 4 - Math.random() * 9; y = a.top + 85 + Math.random() * (a.bot - a.top - 80); }
  else if (s < 0.8) { x = a.cx + a.hw + 4 + Math.random() * 9; y = a.top + 85 + Math.random() * (a.bot - a.top - 80); }
  else { x = a.cx - a.hw + Math.random() * 2 * a.hw; y = a.bot + 4 + Math.random() * 9; vx = (x < a.cx ? -1 : 1) * 0.55; }
  newBubble(x, y, vx);
}
function updateBubbles(k) {
  var stop = CAV.top + CRUST_H + 3;
  for (var i = dynBubbles.length - 1; i >= 0; i--) {
    var b = dynBubbles[i];
    b.y -= b.vy * k; b.ph += 0.15 * k;
    b.x += b.vx * k + Math.sin(b.ph) * 0.35 * k;
    if (b.y < stop) { b.el.remove(); dynBubbles.splice(i, 1); }
    else b.el.center(b.x, b.y);
  }
}

/* ---------- highlight ---------- */
function setHighlight(key) {
  gHL.clear(); hlBoxes = [];
  var gs = anodeGeom(), pt = padTopY(), boxes = [];
  if (key === 'electrolyte') boxes.push([CAV.x0 + 2, CAV.top + CRUST_H, CAV.x1 - CAV.x0 - 4, pt - CAV.top - CRUST_H]);
  if (key === 'bubbles' || key === 'anodes')
    gs.forEach(function (a) { boxes.push([a.cx - a.hw - 18, a.top - 8, 2 * a.hw + 36, a.bot - a.top + 30]); });
  if (key === 'metal') boxes.push([CAV.x0, pt - 3, CAV.x1 - CAV.x0, padT + 22]);
  boxes.forEach(function (b) {
    hlBoxes.push(gHL.rect(b[2], b[3]).move(b[0], b[1]).fill('none')
      .stroke({ color: '#ff7a00', width: 4, dasharray: '12,8' }).radius(4));
  });
}

/* ---------- interaction handlers ---------- */
function update_appliedCurrent(v) { cur = v; }
function toggle_anodeWear(on) { wearOn = on; buildAnodes(); makeIons(); setHighlight(curHL); }
function toggle_electrolysisAnimation(on) { running = on; }
function trigger_tapMetal() { padT = PAD_BASE; redrawMelt(); }

/* ---------- animation loop ---------- */
var lastT = 0;
function frame(ts) {
  var dt = lastT ? Math.min(60, ts - lastT) : 16; lastT = ts;
  var cf = cur / 150;
  if (running && cur > 0) {
    spawnAcc += cf * dt * 0.055;
    while (spawnAcc > 1) { spawnAcc -= 1; spawnBubble(); }
    padT = Math.min(PAD_MAX, padT + cf * dt * 0.0032);
    redrawMelt();
    moveIons(cf * dt / 16);
    gIons.opacity(1);
  } else {
    gIons.opacity(0);
  }
  updateBubbles((running ? Math.max(0.35, cf) : 0.35) * dt / 16);
  if (hlBoxes.length) {
    var o = 0.45 + 0.55 * Math.abs(Math.sin(ts / 420));
    hlBoxes.forEach(function (r) { r.opacity(o); });
  }
  requestAnimationFrame(frame);
}

