var stepIdx = 0, curHL = null;

function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  var sl = document.getElementById('appliedCurrentInput');
  sl.value = s.cur; document.getElementById('appliedCurrentVal').value = s.cur;
  update_appliedCurrent(s.cur);
  var cb = document.getElementById('anodeWearInput');
  if (cb.checked !== s.wear) { cb.checked = s.wear; toggle_anodeWear(s.wear); }
  var an = document.getElementById('electrolysisAnimationInput');
  an.checked = true; toggle_electrolysisAnimation(true);
  if (s.cur === 0) { padT = PAD_BASE; redrawMelt(); }
  curHL = s.hl; setHighlight(curHL);
  document.getElementById('demoTitle').textContent = s.t;
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

